import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Flow, wfa, FlowArray, ActionDefinition } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// -----------------------------------------------------------------------------
// Action with FlowArray input/output
// -----------------------------------------------------------------------------
export const tagsAction = ActionDefinition({
    $id: Now.ID['act_tags'],
    name: 'Tags Action',
    category: 'Examples',
    annotation: 'Takes array of tags and echoes them',
    inputs: {
        tags: FlowArray({
            label: 'Tags',
            mandatory: true,
            elementType: StringColumn({ mandatory: true }),
            childName: 'tag_child0',
        }),
    },
    outputs: {
        echoed: FlowArray({
            label: 'Echoed',
            mandatory: true,
            elementType: StringColumn({ mandatory: true }),
            childName: 'tag_child0',
        }),
        errors: FlowArray({
            label: 'Errors',
            mandatory: false,
            elementType: StringColumn({ mandatory: true }),
            childName: 'error_child0',
        }),
    },
})

// -----------------------------------------------------------------------------
// Flow definition that calls the Action
// -----------------------------------------------------------------------------
Flow(
    {
        $id: Now.ID['flow_array_example'],
        name: 'Flow - FlowArray Example',
        description: 'Calls action with FlowArray input/output',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trg_arr'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_t) => {
        wfa.action(
            tagsAction,
            { $id: Now.ID['act_inst_tags'] },
            {
                tags: ['alpha', 'beta', 'gamma'],
            }
        )
    }
)
